export const C=299792458, TAU=2*Math.PI;
export const db10=x=>x>0?10*Math.log10(x):-Infinity;
export const wavelength=f=>C/(f*1e9);
export function rng32(seed){let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
export function normal(r){let u=0,v=0;while(!u)u=r();while(!v)v=r();return Math.sqrt(-2*Math.log(u))*Math.cos(TAU*v)}
export function formation(c){const n=c.nodes,B=c.baselineM,z=c.rangeKm*1000,p=[];if(n===1)return[[0,0,z]];if(c.formation==='Ring'){for(let i=0;i<n;i++){let a=TAU*i/n;p.push([B/2*Math.cos(a),B/2*Math.sin(a),z])}}else if(c.formation==='Line'){for(let i=0;i<n;i++)p.push([-B/2+B*i/(n-1),0,z])}else if(c.formation==='Random'){let r=rng32(c.seed),R=B/2;for(let i=0;i<n;i++){let rr=R*Math.sqrt(r()),a=TAU*r();p.push([rr*Math.cos(a),rr*Math.sin(a),z])}}else{let cols=Math.ceil(Math.sqrt(n)),rows=Math.ceil(n/cols),sx=cols>1?B/(cols-1):0,sy=rows>1?B/(rows-1):0;for(let i=0;i<n;i++){let x=-B/2+(i%cols)*sx,y=-B/2+Math.floor(i/cols)*sy;p.push([x,y,z])}let xs=p.map(x=>x[0]),ys=p.map(x=>x[1]),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2;p.forEach(q=>{q[0]-=cx;q[1]-=cy})}return p}
export function estimates(t,c){let r=rng32(c.seed+101),s=c.pathErrorMm/1000;return t.map(p=>[p[0],p[1],p[2]+normal(r)*s])}
const dist=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1],a[2]-b[2]);
export function commands(t,e,c,q=[0,0,0]){let k=TAU/wavelength(c.freqGHz);return t.map((p,i)=>c.command==='None'?0:k*dist(c.command==='Oracle'?p:e[i],q))}
export function errors(c){let r=rng32(c.seed+202),s=c.rfPhaseRmsDeg*Math.PI/180;return Array.from({length:c.nodes},()=>({phase:normal(r)*s,df:normal(r)*c.freqOffsetHz}))}
export function phases(t,e,c,time=0,q=[0,0,0],err=errors(c)){let k=TAU/wavelength(c.freqGHz),cmd=commands(t,e,c,[0,0,0]);return t.map((p,i)=>-k*dist(p,q)+cmd[i]+err[i].phase+TAU*err[i].df*time)}
export function metrics(c,time=0){let t=formation(c),e=estimates(t,c),ph=phases(t,e,c,time),n=t.length,p=c.powerMode==='Per node'?c.totalPowerW:c.totalPowerW/n,re=0,im=0;for(const a of ph){re+=Math.sqrt(p)*Math.cos(a);im+=Math.sqrt(p)*Math.sin(a)}let actual=re*re+im*im,ideal=(n*Math.sqrt(p))**2,incoh=n*p;return{truth:t,estimate:e,phases:ph,actual,ideal,incoh,coherence:actual/ideal,coherenceLossDb:actual? -db10(actual/ideal):Infinity,gainVsIncoherentDb:actual?db10(actual/incoh):-Infinity}}
export function field(c,t,e,x,y,time=0,err=errors(c)){let q=[x,y,0],ph=phases(t,e,c,time,q,err),p=c.powerMode==='Per node'?c.totalPowerW:c.totalPowerW/c.nodes,re=0,im=0;for(const a of ph){re+=Math.sqrt(p)*Math.cos(a);im+=Math.sqrt(p)*Math.sin(a)}return re*re+im*im}
export function focusMap(c,size=71,time=0){let t=formation(c),e=estimates(t,c),err=errors(c),half=c.mapSpanKm*500,v=new Float64Array(size*size),max=0;for(let j=0;j<size;j++)for(let i=0;i<size;i++){let x=-half+2*half*i/(size-1),y=-half+2*half*j/(size-1),z=field(c,t,e,x,y,time,err);v[j*size+i]=z;max=Math.max(max,z)}return{size,values:v,max,center:field(c,t,e,0,0,time,err),half}}
export function requirement(n,loss,f){let target=10**(-loss/10),x=(target-1/n)/(1-1/n);if(x<=0||x>1)return null;let s=Math.sqrt(-Math.log(x)),lam=wavelength(f);return{phaseRmsDeg:s*180/Math.PI,pathRmsMm:s*lam/TAU*1000,timeRmsPs:s/(TAU*f*1e9)*1e12}}
export const farFieldKm=(B,f)=>2*B*B/wavelength(f)/1000;
